 function priceFor(service,raw,unknown=false) {
  if(unknown) return {kind:'custom'};
  if(String(raw).trim()==='') return {kind:'empty'};
  const n=Number(raw);
  if(!Number.isFinite(n)||n<=0) return {kind:'invalid'};
  const i=service.limits.findIndex(limit=>n<=limit);
  return i<0?{kind:'custom'}:{kind:'priced',price:service.prices[i],n};
 }
 // Bundle savings apply only to distinct, priced services; materials and fees are excluded from these rates.
 function bundleTotals(items) {
  const unique=[...new Map(items.map(item=>[item.service.id,item])).values()];
  const pricedItems=unique.filter(item=>item.result.kind==='priced');
  const subtotalCents=pricedItems.reduce((sum,item)=>sum+Math.round(item.result.price*100),0);
  const eligible=pricedItems.length>=3;
  const savingsCents=eligible?Math.round(subtotalCents*0.1):0;
  return {subtotal:subtotalCents/100,savings:savingsCents/100,sum:(subtotalCents-savingsCents)/100,eligible,
   custom:unique.filter(item=>item.result.kind==='custom').length,priced:pricedItems.length};
 }
