 const storageKey='lakeland-price-estimate-v3'+(demo?'-preview':'');
 let storageReady=false;
 function persist(){if(!storageReady)return;try{localStorage.setItem(storageKey,JSON.stringify({saved:[...cart.values()].map(i=>({id:i.service.id,raw:i.raw,unknown:i.unknown})),drafts:[...drafts],touched:[...touched],areas:[...areaSets],selected:selected.id}));$('pc-save-status').textContent='Services and measurements saved on this device. Contact details are not saved.';}catch{$('pc-save-status').textContent='Saving is unavailable in this browser. Your estimate still works until you leave or refresh.';}}
 function dirtyServices(){return services.filter(s=>{if(!touched.has(s.id))return false;const d=drafts.get(s.id),i=cart.get(s.id);return d&&(!i||d.raw!==i.raw||d.unknown!==i.unknown);});}
