 function renderAreas(){const rows=areaSets.get(selected.id)||[{length:'',width:''}];areaSets.set(selected.id,rows);const holder=$('pc-areas');holder.replaceChildren();rows.forEach((row,index)=>{const wrap=document.createElement('div');wrap.className='pc-area-row';for(const key of ['length','width']){const label=document.createElement('label');label.textContent='Area '+(index+1)+' '+key+' (ft)';const input=document.createElement('input');input.type='number';input.min='0.01';input.step='any';input.inputMode='decimal';input.value=row[key];input.setAttribute('aria-label',label.textContent);input.addEventListener('input',()=>{row[key]=input.value;areaTotal();persist();});label.append(input);wrap.append(label);}const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.setAttribute('aria-label','Remove area '+(index+1));remove.addEventListener('click',()=>{rows.splice(index,1);if(!rows.length)rows.push({length:'',width:''});renderAreas();persist();});wrap.append(remove);holder.append(wrap);});areaTotal();}
 function areaTotal(){const rows=areaSets.get(selected.id)||[];const valid=rows.length&&rows.every(r=>Number.isFinite(Number(r.length))&&Number(r.length)>0&&Number.isFinite(Number(r.width))&&Number(r.width)>0);const sum=rows.reduce((n,r)=>n+Number(r.length)*Number(r.width),0);const okay=valid&&Number.isFinite(sum)&&sum>0;$('pc-use-area').disabled=!okay;$('pc-area-total').textContent=okay?'Combined area: '+Math.ceil(sum).toLocaleString()+' sq ft':'Enter a positive length and width for each area.';return okay?Math.ceil(sum):null;}
 $('pc-another-area').addEventListener('click',()=>{const rows=areaSets.get(selected.id);if(rows.length>=12)return;rows.push({length:'',width:''});renderAreas();persist();});
