 try{const data=JSON.parse(localStorage.getItem(storageKey)||'null');if(data&&Array.isArray(data.saved)){for(const i of data.saved.slice(0,8)){const service=services.find(s=>s.id===i.id);if(!service||typeof i.raw!=='string'||i.raw.length>30||typeof i.unknown!=='boolean')continue;const result=priceFor(service,i.raw,i.unknown);if(['priced','custom'].includes(result.kind))cart.set(i.id,{service,raw:i.raw,unknown:i.unknown,result});}for(const [id,d] of Array.isArray(data.drafts)?data.drafts.slice(0,8):[]){if(services.some(s=>s.id===id)&&d&&typeof d.raw==='string'&&d.raw.length<31&&typeof d.unknown==='boolean')drafts.set(id,d);}for(const id of Array.isArray(data.touched)?data.touched:[])if(services.some(s=>s.id===id))touched.add(id);for(const [id,rows] of Array.isArray(data.areas)?data.areas.slice(0,8):[])if(['lawn','driveway'].includes(id)&&Array.isArray(rows)&&rows.length<=12&&rows.every(r=>r&&typeof r.length==='string'&&typeof r.width==='string'&&r.length.length<31&&r.width.length<31))areaSets.set(id,rows);selected=services.find(s=>s.id===data.selected)||selected;}}catch{/* Storage may be disabled or contain invalid old data. */}
